INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "阮结卒，成及代润州制置使", "start_year": 889, "end_year": 889, "time_original": "889年五月甲辰", "dynasty": "唐", "description": "润州制置使阮结去世，钱镠以静江都将成及代之。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9e651a77-437d-529d-8396-b6cbacee83dd"}, {"title": "李罕之李存孝拔磁洺二州", "start_year": 889, "end_year": 889, "time_original": "889年六月；发兵具体日未载", "dynasty": "唐", "description": "李克用大发兵，遣李罕之、李存孝攻孟方立，六月攻取磁、洺二州。", "phases": [], "location_name": "磁州、洺州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "027a30b5-61a7-5722-b61e-c290d6cb70b1"}, {"title": "孟方立援军败于琉璃陂", "start_year": 889, "end_year": 889, "time_original": "889年六月条；具体日未载", "dynasty": "唐", "description": "孟方立遣马溉、袁奉韬率军抵抗，在琉璃陂大败，两将被擒；李克用乘胜进攻邢州。", "phases": [], "location_name": "琉璃陂", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d5efd110-e8b6-5e45-be20-5e6516984eef"}, {"title": "孟方立饮药死，孟迁被奉留后", "start_year": 889, "end_year": 889, "time_original": "889年六月条；邢州被攻后", "dynasty": "唐", "description": "《通鉴》记孟方立因诸将不为所用，惭惧饮药而死；其弟、摄洺州刺史孟迁被众人奉为留后，向朱全忠求援。", "phases": [], "location_name": "邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bf6d7574-a52b-56fd-80e1-6a1a6f081e89"}, {"title": "王虔裕间道援邢州", "start_year": 889, "end_year": 889, "time_original": "889年六月条；孟迁求援后", "dynasty": "唐", "description": "朱全忠向魏博借道遭罗弘信拒绝，改遣王虔裕率精兵数百，间道进入邢州共同守城。", "phases": [], "location_name": "魏博、邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a3c6199e-997c-58e2-a843-77c2ff8fb3cc"}, {"title": "宣州饥困，周进思逐赵锽", "start_year": 889, "end_year": 889, "time_original": "889年六月后条；具体日未载", "dynasty": "唐", "description": "杨行密围宣州，城中粮食耗尽，《通鉴》记人相啖；周进思据城逐赵锽，赵锽欲奔广陵，被田頵追擒。", "phases": [], "location_name": "宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f865fe00-8ccc-5767-87c5-c00e8f581b61"}, {"title": "宣州执周进思降，徐温赈饥", "start_year": 889, "end_year": 889, "time_original": "889年六月后条；逐赵锽后未几", "dynasty": "唐", "description": "城中拘执周进思投降，杨行密入宣州。诸将争取金帛，徐温独据米囷，煮粥赈济饥民。", "phases": [], "location_name": "宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "af585641-ce60-51dd-96a8-50cef864fae8"}, {"title": "杨行密释周本并任裨将", "start_year": 889, "end_year": 889, "time_original": "889年六月后条；宣州战事中具体日未载", "dynasty": "唐", "description": "赵锽部将周本被杨行密俘获后释放，并被任为裨将；《通鉴》称周本为宿松人，勇冠军中。", "phases": [], "location_name": "宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2823e264-a61e-5bc5-ab2f-29d51384e6bb"}, {"title": "杨行密以宗女妻李德诚", "start_year": 889, "end_year": 889, "time_original": "889年六月后条；赵锽败后", "dynasty": "唐", "description": "赵锽兵败后，李德诚仍随从不去；杨行密以宗女嫁给李德诚。《通鉴》称李德诚为西华人。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "163344df-2e3f-5005-8f50-5d6f031c1ec2"}, {"title": "杨行密受任宣歙观察使", "start_year": 889, "end_year": 889, "time_original": "889年六月后条；具体日未载", "dynasty": "唐", "description": "杨行密上表朝廷，朝廷诏以其为宣歙观察使。", "phases": [], "location_name": "宣歙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4e6b1d65-8b11-5a9b-bcbb-9256adcad498"}, {"title": "杨行密从袁袭议杀赵锽", "start_year": 889, "end_year": 889, "time_original": "889年六月后条；宣州战后", "dynasty": "唐", "description": "朱全忠因与赵锽有旧，遣使索要赵锽；杨行密咨询袁袭，采纳其斩首以送朱全忠的建议。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f9e7fa6a-9edf-5f22-b975-8acd8bfb6d3b"}, {"title": "袁袭卒，杨行密哀悼", "start_year": null, "end_year": null, "time_original": "宣州战后未几；具体年日待核", "dynasty": "唐", "description": "袁袭不久去世，杨行密哭悼，称失去股肱，并将其短寿与屡劝杀人联系。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f411927e-a4e6-516a-ae91-a0888bb331ea"}, {"title": "蔡俦以庐州降孙儒", "start_year": 889, "end_year": 889, "time_original": "889年六月后条；具体日未载", "dynasty": "唐", "description": "孙儒遣兵攻庐州，蔡俦以州降孙儒。", "phases": [], "location_name": "庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e432b948-4fc5-5036-83ee-f5950b4a21b7"}, {"title": "朱珍据萧县与时溥相拒", "start_year": 889, "end_year": 889, "time_original": "889年七月前；具体日未载", "dynasty": "唐", "description": "朱珍攻取萧县并据守，与时溥相拒，朱全忠欲亲自前往。", "phases": [], "location_name": "萧县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e6d38c74-8c0d-5443-a3b6-bc9d124b9dd0"}, {"title": "朱珍杀李唐宾并报谋叛", "start_year": 889, "end_year": 889, "time_original": "889年七月前；具体日未载", "dynasty": "唐", "description": "朱珍命诸军修葺马厩，李唐宾部将严郊怠慢，军吏责备；李唐宾向朱珍申诉，朱珍怒其无礼而杀之，向朱全忠报告称李唐宾谋叛。", "phases": [], "location_name": "萧县军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d837c997-02c4-5e46-83e9-5d05c3c12e29"}, {"title": "敬翔缓报并谋慰抚军中", "start_year": 889, "end_year": 889, "time_original": "889年七月前；李唐宾被杀后", "dynasty": "唐", "description": "敬翔担忧朱全忠仓促处置，留报信者到夜间才禀报，又建议假意拘收李唐宾妻子入狱并遣骑慰抚军中；朱全忠采纳，军中始安。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "ed53e3a9-6a11-539d-a67c-79c3c5782e4c"}, {"title": "朱全忠诛朱珍，霍存等求情", "start_year": 889, "end_year": 889, "time_original": "889年七月；赴萧县途中", "dynasty": "唐", "description": "朱全忠赴萧县，未到时拘执迎接的朱珍，以专杀罪责诛之；霍存等数十名将领叩头求情，朱全忠发怒掷床，诸将退下。", "phases": [], "location_name": "赴萧县途中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8d1c9e73-b8dc-56f0-89e5-d28792684367"}, {"title": "庞师古代朱珍为都指挥使", "start_year": 889, "end_year": 889, "time_original": "889年七月丁未", "dynasty": "唐", "description": "朱全忠抵达萧县，以庞师古代朱珍为都指挥使。", "phases": [], "location_name": "萧县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7e9a806a-4108-5d48-afa6-58a890dbba61"}, {"title": "朱全忠攻时溥遇雨退兵", "start_year": 889, "end_year": 889, "time_original": "889年八月丙子", "dynasty": "唐", "description": "朱全忠进攻时溥营壁，遇大雨后撤军。", "phases": [], "location_name": "时溥军壁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0f4e4aba-f843-56d8-90c3-7e95ed3f60b0"}, {"title": "王敬武卒，王师范被推平卢留后", "start_year": 889, "end_year": 889, "time_original": "889年十月", "dynasty": "唐", "description": "平卢节度使王敬武去世，军中推其子、时年十六的王师范为留后，棣州刺史张蟾不从。", "phases": [], "location_name": "平卢", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c4236cec-4515-5341-a2f8-8daf8289f4ec"}, {"title": "崔安潜受任平卢，张蟾迎讨王师范", "start_year": 889, "end_year": 889, "time_original": "889年十月；具体日未载", "dynasty": "唐", "description": "朝廷命太子少师崔安潜兼侍中、充平卢节度使；张蟾迎其至州，共讨王师范。", "phases": [], "location_name": "平卢、棣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8c11bbca-d1d7-5293-b3b9-6404301a15fa"}, {"title": "杜孺休任苏州刺史，钱镠留沈粲制置", "start_year": 889, "end_year": 889, "time_original": "889年十月后条；具体日未载", "dynasty": "唐", "description": "朝廷以给事中杜孺休为苏州刺史，钱镠不悦，以知州事沈粲为制置指挥使。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e2caa27b-fad2-51ca-9bd1-2700bdc17486"}, {"title": "杨行密遣田頵攻常州", "start_year": 889, "end_year": 889, "time_original": "889年十月后条；具体日未载", "dynasty": "唐", "description": "杨行密遣马步都虞候田頵等进攻常州。", "phases": [], "location_name": "常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a81b4ec3-c590-5de9-88f6-7909b103a4a5"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

